CREATE TABLE "app_user" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_code" varchar(64) UNIQUE NOT NULL,
  "role_code" varchar(20) NOT NULL DEFAULT 'RESIDENT',
  "nickname" varchar(50),
  "phone_hash" varchar(64) UNIQUE,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "last_login_at" timestamp,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "user_profile" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "profile_type" varchar(20) NOT NULL,
  "profile_label" varchar(50) NOT NULL,
  "source" varchar(20) NOT NULL DEFAULT 'FORM',
  "confidence" decimal(5,2),
  "version_no" int NOT NULL DEFAULT 1,
  "is_current" char(1) NOT NULL DEFAULT 'Y',
  "created_at" timestamp NOT NULL
);

CREATE TABLE "profile_tag" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag_code" varchar(40) UNIQUE NOT NULL,
  "tag_name" varchar(50) NOT NULL,
  "role_scope" varchar(20) NOT NULL DEFAULT 'ALL',
  "dimension_code" varchar(30) NOT NULL,
  "default_weight" decimal(5,2) NOT NULL DEFAULT 20,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "created_at" timestamp NOT NULL
);

CREATE TABLE "user_profile_tag" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" bigint NOT NULL,
  "tag_id" bigint NOT NULL,
  "weight" decimal(5,2) NOT NULL DEFAULT 20,
  "selected_at" timestamp NOT NULL
);

CREATE TABLE "profile_dimension_weight" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "profile_id" bigint NOT NULL,
  "dimension_code" varchar(30) NOT NULL,
  "dimension_name" varchar(50) NOT NULL,
  "weight" decimal(5,2) NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "district" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_code" varchar(40) UNIQUE NOT NULL,
  "district_name" varchar(100) NOT NULL,
  "parent_id" bigint,
  "district_level" varchar(20) NOT NULL,
  "city_code" varchar(20) NOT NULL,
  "center_lng" decimal(10,6),
  "center_lat" decimal(10,6),
  "boundary_geojson" text,
  "area_sqm" decimal(12,2),
  "resident_count" int,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "population_grid" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "grid_code" varchar(40) NOT NULL,
  "grid_level" varchar(20) NOT NULL DEFAULT 'GRID_250M',
  "center_lng" decimal(10,6) NOT NULL,
  "center_lat" decimal(10,6) NOT NULL,
  "population" int NOT NULL,
  "density" decimal(12,2),
  "data_date" date NOT NULL,
  "source" varchar(20) NOT NULL DEFAULT 'GOV',
  "created_at" timestamp NOT NULL
);

CREATE TABLE "road_node" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "node_code" varchar(40) UNIQUE NOT NULL,
  "district_id" bigint,
  "lng" decimal(10,6) NOT NULL,
  "lat" decimal(10,6) NOT NULL,
  "node_type" varchar(20) NOT NULL DEFAULT 'INTERSECTION',
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "road_segment" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "segment_code" varchar(50) UNIQUE NOT NULL,
  "district_id" bigint,
  "from_node_id" bigint NOT NULL,
  "to_node_id" bigint NOT NULL,
  "road_name" varchar(100),
  "road_level" varchar(20) NOT NULL DEFAULT 'BRANCH',
  "length_m" decimal(10,2) NOT NULL,
  "walk_time_s" int NOT NULL,
  "is_walkable" char(1) NOT NULL DEFAULT 'Y',
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "facility_category" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_code" varchar(40) UNIQUE NOT NULL,
  "category_name" varchar(50) NOT NULL,
  "dimension_code" varchar(30) NOT NULL,
  "dimension_name" varchar(50) NOT NULL,
  "icon" varchar(100),
  "sort_no" int NOT NULL DEFAULT 0,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "created_at" timestamp NOT NULL
);

CREATE TABLE "poi_facility" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "category_id" bigint NOT NULL,
  "poi_name" varchar(200) NOT NULL,
  "lng" decimal(10,6) NOT NULL,
  "lat" decimal(10,6) NOT NULL,
  "address" varchar(255),
  "business_status" varchar(20) NOT NULL DEFAULT 'OPEN',
  "source" varchar(20) NOT NULL,
  "source_poi_id" varchar(100) NOT NULL,
  "telephone" varchar(50),
  "first_seen_at" timestamp NOT NULL,
  "last_seen_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "is_valid" char(1) NOT NULL DEFAULT 'Y'
);

CREATE TABLE "poi_change_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "poi_id" bigint,
  "batch_id" bigint NOT NULL,
  "change_type" varchar(20) NOT NULL,
  "change_summary" varchar(500),
  "before_json" text,
  "after_json" text,
  "changed_at" timestamp NOT NULL
);

CREATE TABLE "resident_assessment" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "resident_code" varchar(64) NOT NULL,
  "user_id" bigint,
  "district_id" bigint NOT NULL,
  "profile_id" bigint,
  "batch_id" bigint,
  "radius_m" int NOT NULL DEFAULT 1080,
  "total_score" int NOT NULL,
  "profile_label" varchar(50),
  "insight" varchar(1000),
  "assessed_at" timestamp NOT NULL
);

CREATE TABLE "assessment_dimension" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "assessment_id" bigint NOT NULL,
  "dimension_code" varchar(30) NOT NULL,
  "dimension_name" varchar(50) NOT NULL,
  "dimension_score" int NOT NULL,
  "weight" decimal(5,2) NOT NULL,
  "facility_count" int NOT NULL DEFAULT 0
);

CREATE TABLE "assessment_facility_stat" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "assessment_id" bigint NOT NULL,
  "category_id" bigint NOT NULL,
  "facility_count" int NOT NULL DEFAULT 0,
  "nearest_distance_m" decimal(10,2),
  "status" varchar(20)
);

CREATE TABLE "district_score_snapshot" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "batch_id" bigint,
  "coverage_pct" int NOT NULL,
  "avg_score" decimal(5,2) NOT NULL,
  "rank_no" int,
  "resident_count" int,
  "scored_at" timestamp NOT NULL
);

CREATE TABLE "site_candidate" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "batch_id" bigint,
  "candidate_name" varchar(100) NOT NULL,
  "business_type" varchar(100),
  "lng" decimal(10,6),
  "lat" decimal(10,6),
  "population_index" decimal(10,2),
  "competitor_count" int,
  "demand_level" varchar(10),
  "competition_level" varchar(10),
  "rent_min" decimal(8,2),
  "rent_max" decimal(8,2),
  "site_score" int,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "site_score_item" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "candidate_id" bigint NOT NULL,
  "score_item" varchar(50) NOT NULL,
  "item_score" decimal(5,2) NOT NULL,
  "weight" decimal(5,2) NOT NULL,
  "reason" varchar(255)
);

CREATE TABLE "merchant_intent" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "merchant_name" varchar(100) NOT NULL,
  "business_type" varchar(100) NOT NULL,
  "contact" varchar(200) NOT NULL,
  "contact_masked" varchar(20),
  "district_id" bigint,
  "candidate_id" bigint,
  "budget_min" decimal(8,2),
  "budget_max" decimal(8,2),
  "area_sqm" decimal(8,2),
  "remark" varchar(500),
  "status" varchar(20) NOT NULL DEFAULT 'SUBMITTED',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "merchant_match" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "intent_id" bigint NOT NULL,
  "district_id" bigint NOT NULL,
  "gap_id" bigint,
  "fit_score" int NOT NULL,
  "match_reason" varchar(500),
  "status" varchar(20) NOT NULL DEFAULT 'PENDING',
  "matched_at" timestamp NOT NULL
);

CREATE TABLE "community_gap" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "category_id" bigint NOT NULL,
  "area_name" varchar(100) NOT NULL,
  "issue" varchar(200) NOT NULL,
  "gap_level" varchar(10) NOT NULL,
  "uncovered_residents" int,
  "priority_no" int,
  "batch_id" bigint,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "simulation_record" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "district_id" bigint NOT NULL,
  "category_id" bigint NOT NULL,
  "business_type" varchar(100),
  "lng" decimal(10,6),
  "lat" decimal(10,6),
  "before_coverage" int NOT NULL,
  "after_coverage" int NOT NULL,
  "benefited_residents" int NOT NULL,
  "operator" varchar(50),
  "simulated_at" timestamp NOT NULL
);

CREATE TABLE "sync_batch" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_no" varchar(40) UNIQUE NOT NULL,
  "data_source" varchar(20) NOT NULL,
  "sync_type" varchar(20) NOT NULL,
  "started_at" timestamp NOT NULL,
  "finished_at" timestamp,
  "total_count" int NOT NULL DEFAULT 0,
  "insert_count" int NOT NULL DEFAULT 0,
  "update_count" int NOT NULL DEFAULT 0,
  "close_count" int NOT NULL DEFAULT 0,
  "invalid_count" int NOT NULL DEFAULT 0,
  "status" varchar(20) NOT NULL DEFAULT 'RUNNING',
  "error_msg" varchar(1000),
  "created_at" timestamp NOT NULL
);

CREATE TABLE "data_quality_issue" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_id" bigint NOT NULL,
  "poi_id" bigint,
  "rule_code" varchar(40) NOT NULL,
  "issue_desc" varchar(500) NOT NULL,
  "severity" varchar(20) NOT NULL,
  "is_handled" char(1) NOT NULL DEFAULT 'N',
  "handled_at" timestamp,
  "created_at" timestamp NOT NULL
);

CREATE TABLE "ods_poi_raw" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_id" bigint NOT NULL,
  "source" varchar(20) NOT NULL,
  "source_poi_id" varchar(100) NOT NULL,
  "poi_name" varchar(200),
  "lng" decimal(10,6),
  "lat" decimal(10,6),
  "category_raw" varchar(100),
  "address" varchar(255),
  "raw_json" text NOT NULL,
  "load_at" timestamp NOT NULL,
  "process_status" varchar(20) NOT NULL DEFAULT 'PENDING'
);

CREATE TABLE "ods_population_raw" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_id" bigint NOT NULL,
  "grid_code" varchar(40) NOT NULL,
  "population" int,
  "density" decimal(12,2),
  "data_date" date,
  "raw_json" text NOT NULL,
  "load_at" timestamp NOT NULL,
  "process_status" varchar(20) NOT NULL DEFAULT 'PENDING'
);

CREATE TABLE "ods_road_raw" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_id" bigint NOT NULL,
  "segment_code" varchar(50),
  "raw_json" text NOT NULL,
  "load_at" timestamp NOT NULL,
  "process_status" varchar(20) NOT NULL DEFAULT 'PENDING'
);

CREATE INDEX "idx_app_user_role_status" ON "app_user" ("role_code", "status");

CREATE UNIQUE INDEX "uk_user_profile_ver" ON "user_profile" ("user_id", "version_no");

CREATE INDEX "idx_user_profile_cur" ON "user_profile" ("user_id", "is_current");

CREATE INDEX "idx_profile_tag_dim" ON "profile_tag" ("dimension_code", "role_scope");

CREATE UNIQUE INDEX "uk_profile_tag" ON "user_profile_tag" ("profile_id", "tag_id");

CREATE UNIQUE INDEX "uk_profile_dim" ON "profile_dimension_weight" ("profile_id", "dimension_code");

CREATE INDEX "idx_district_parent" ON "district" ("parent_id");

CREATE INDEX "idx_district_city" ON "district" ("city_code", "district_level");

CREATE UNIQUE INDEX "uk_pop_grid_date" ON "population_grid" ("grid_code", "data_date");

CREATE INDEX "idx_pop_district_date" ON "population_grid" ("district_id", "data_date");

CREATE INDEX "idx_road_node_district" ON "road_node" ("district_id");

CREATE INDEX "idx_road_seg_from" ON "road_segment" ("from_node_id");

CREATE INDEX "idx_road_seg_to" ON "road_segment" ("to_node_id");

CREATE INDEX "idx_road_seg_district" ON "road_segment" ("district_id");

CREATE INDEX "idx_fac_category_dim" ON "facility_category" ("dimension_code", "sort_no");

CREATE UNIQUE INDEX "uk_poi_source" ON "poi_facility" ("source", "source_poi_id");

CREATE INDEX "idx_poi_district_cat" ON "poi_facility" ("district_id", "category_id");

CREATE INDEX "idx_poi_category" ON "poi_facility" ("category_id", "is_valid");

CREATE INDEX "idx_poi_name" ON "poi_facility" ("poi_name");

CREATE INDEX "idx_poi_log_poi" ON "poi_change_log" ("poi_id", "changed_at");

CREATE INDEX "idx_poi_log_batch" ON "poi_change_log" ("batch_id");

CREATE INDEX "idx_assess_district_time" ON "resident_assessment" ("district_id", "assessed_at");

CREATE INDEX "idx_assess_user" ON "resident_assessment" ("user_id", "assessed_at");

CREATE INDEX "idx_assess_batch" ON "resident_assessment" ("batch_id");

CREATE UNIQUE INDEX "uk_assess_dim" ON "assessment_dimension" ("assessment_id", "dimension_code");

CREATE UNIQUE INDEX "uk_assess_category" ON "assessment_facility_stat" ("assessment_id", "category_id");

CREATE UNIQUE INDEX "uk_district_batch" ON "district_score_snapshot" ("district_id", "batch_id");

CREATE INDEX "idx_district_score_time" ON "district_score_snapshot" ("scored_at");

CREATE INDEX "idx_site_district_type" ON "site_candidate" ("district_id", "business_type", "site_score");

CREATE INDEX "idx_site_batch" ON "site_candidate" ("batch_id");

CREATE UNIQUE INDEX "uk_site_score_item" ON "site_score_item" ("candidate_id", "score_item");

CREATE INDEX "idx_intent_status_time" ON "merchant_intent" ("status", "created_at");

CREATE INDEX "idx_intent_district" ON "merchant_intent" ("district_id");

CREATE INDEX "idx_intent_candidate" ON "merchant_intent" ("candidate_id");

CREATE INDEX "idx_match_intent" ON "merchant_match" ("intent_id");

CREATE INDEX "idx_match_gap" ON "merchant_match" ("gap_id");

CREATE INDEX "idx_match_district_score" ON "merchant_match" ("district_id", "fit_score");

CREATE INDEX "idx_gap_district_level" ON "community_gap" ("district_id", "gap_level");

CREATE INDEX "idx_gap_category" ON "community_gap" ("category_id");

CREATE INDEX "idx_gap_batch" ON "community_gap" ("batch_id");

CREATE INDEX "idx_sim_district_time" ON "simulation_record" ("district_id", "simulated_at");

CREATE INDEX "idx_sync_status_time" ON "sync_batch" ("status", "started_at");

CREATE INDEX "idx_dq_batch_severity" ON "data_quality_issue" ("batch_id", "severity", "is_handled");

CREATE INDEX "idx_ods_poi_batch" ON "ods_poi_raw" ("batch_id", "process_status");

CREATE INDEX "idx_ods_poi_source" ON "ods_poi_raw" ("source", "source_poi_id");

CREATE INDEX "idx_ods_pop_batch" ON "ods_population_raw" ("batch_id", "process_status");

CREATE INDEX "idx_ods_road_batch" ON "ods_road_raw" ("batch_id", "process_status");

COMMENT ON TABLE "app_user" IS '用户账号表：三类使用者的统一账号，只保存脱敏业务编号与手机号哈希，不落库明文手机号。';

COMMENT ON COLUMN "app_user"."id" IS '自增主键';

COMMENT ON COLUMN "app_user"."user_code" IS '脱敏编号，居民 R、商户 M、社区 C 前缀';

COMMENT ON COLUMN "app_user"."role_code" IS 'RESIDENT 居民 / MERCHANT 商户 / COMMUNITY 社区 / ADMIN 管理员';

COMMENT ON COLUMN "app_user"."nickname" IS '展示名称，可为空';

COMMENT ON COLUMN "app_user"."phone_hash" IS 'SHA-256 加盐哈希，用于登录匹配，不可逆';

COMMENT ON COLUMN "app_user"."status" IS 'ACTIVE/DISABLED/DELETED';

COMMENT ON COLUMN "app_user"."last_login_at" IS 'UTC 时间';

COMMENT ON COLUMN "app_user"."created_at" IS '创建时间';

COMMENT ON COLUMN "app_user"."updated_at" IS '更新时间';

COMMENT ON TABLE "user_profile" IS '用户画像表：一次画像生成的版本化结果，保留历史版本，is_current 标记当前生效画像。';

COMMENT ON COLUMN "user_profile"."id" IS '主键';

COMMENT ON COLUMN "user_profile"."user_id" IS '所属用户';

COMMENT ON COLUMN "user_profile"."profile_type" IS '居民画像或商户画像';

COMMENT ON COLUMN "user_profile"."profile_label" IS '如“青年夜班画像”“稳健型商户画像”';

COMMENT ON COLUMN "user_profile"."source" IS '表单/多轮对话/导入';

COMMENT ON COLUMN "user_profile"."confidence" IS '0-100，表示标签可信程度';

COMMENT ON COLUMN "user_profile"."version_no" IS '从 1 递增';

COMMENT ON COLUMN "user_profile"."is_current" IS 'Y/N，同一用户仅一条 Y';

COMMENT ON COLUMN "user_profile"."created_at" IS '创建时间';

COMMENT ON TABLE "profile_tag" IS '画像标签字典表：可配置的关注点标签库，按角色与评分维度归类，供画像生成和权重计算使用。';

COMMENT ON COLUMN "profile_tag"."id" IS '主键';

COMMENT ON COLUMN "profile_tag"."tag_code" IS '如 NIGHT_MEDICAL、FRESH_FOOD';

COMMENT ON COLUMN "profile_tag"."tag_name" IS '如“夜间就医”';

COMMENT ON COLUMN "profile_tag"."role_scope" IS '适用角色范围';

COMMENT ON COLUMN "profile_tag"."dimension_code" IS '关联 FACILITY_DIMENSION 编码';

COMMENT ON COLUMN "profile_tag"."default_weight" IS '0-100 百分比';

COMMENT ON COLUMN "profile_tag"."status" IS '状态';

COMMENT ON COLUMN "profile_tag"."created_at" IS '创建时间';

COMMENT ON TABLE "user_profile_tag" IS '用户画像标签明细表：画像与标签的多对多关联，记录用户勾选/对话提取出的标签及个性化权重。';

COMMENT ON COLUMN "user_profile_tag"."id" IS '主键';

COMMENT ON COLUMN "user_profile_tag"."profile_id" IS '画像';

COMMENT ON COLUMN "user_profile_tag"."tag_id" IS '标签';

COMMENT ON COLUMN "user_profile_tag"."weight" IS '0-100 百分比，参与加权评分';

COMMENT ON COLUMN "user_profile_tag"."selected_at" IS '选取时间';

COMMENT ON TABLE "profile_dimension_weight" IS '画像维度权重表：画像对五个评分维度的最终权重，居民评估时按该表动态加权，权重之和应为 100。';

COMMENT ON COLUMN "profile_dimension_weight"."id" IS '主键';

COMMENT ON COLUMN "profile_dimension_weight"."profile_id" IS '画像';

COMMENT ON COLUMN "profile_dimension_weight"."dimension_code" IS 'FRESH/MEDICAL/EDU/TRAFFIC/NIGHT';

COMMENT ON COLUMN "profile_dimension_weight"."dimension_name" IS '生鲜购物/医疗健康/亲子教育/交通通勤/夜间服务';

COMMENT ON COLUMN "profile_dimension_weight"."weight" IS '0-100 百分比';

COMMENT ON COLUMN "profile_dimension_weight"."updated_at" IS '更新时间';

COMMENT ON TABLE "district" IS '社区片区表：街道—社区—网格三级空间主数据，是设施、评估、选址和治理的公共维度。';

COMMENT ON COLUMN "district"."id" IS '主键';

COMMENT ON COLUMN "district"."district_code" IS '行政区划码+序号，全局唯一';

COMMENT ON COLUMN "district"."district_name" IS '片区名称';

COMMENT ON COLUMN "district"."parent_id" IS '自关联，街道→社区→网格';

COMMENT ON COLUMN "district"."district_level" IS 'STREET/COMMUNITY/GRID';

COMMENT ON COLUMN "district"."city_code" IS 'GB/T 2260 六位代码';

COMMENT ON COLUMN "district"."center_lng" IS 'WGS84，单位度';

COMMENT ON COLUMN "district"."center_lat" IS 'WGS84，单位度';

COMMENT ON COLUMN "district"."boundary_geojson" IS '片区边界，GeoJSON Polygon';

COMMENT ON COLUMN "district"."area_sqm" IS '平方米';

COMMENT ON COLUMN "district"."resident_count" IS '人';

COMMENT ON COLUMN "district"."status" IS '状态';

COMMENT ON COLUMN "district"."created_at" IS '创建时间';

COMMENT ON COLUMN "district"."updated_at" IS '更新时间';

COMMENT ON TABLE "population_grid" IS '人口栅格表：按栅格与统计日期保存常住人口和密度，是商户选址人口指数与社区覆盖测算的输入。';

COMMENT ON COLUMN "population_grid"."id" IS '主键';

COMMENT ON COLUMN "population_grid"."district_id" IS '所属片区';

COMMENT ON COLUMN "population_grid"."grid_code" IS '统一栅格编码';

COMMENT ON COLUMN "population_grid"."grid_level" IS '栅格精度';

COMMENT ON COLUMN "population_grid"."center_lng" IS '栅格中心经度';

COMMENT ON COLUMN "population_grid"."center_lat" IS '栅格中心纬度';

COMMENT ON COLUMN "population_grid"."population" IS '人';

COMMENT ON COLUMN "population_grid"."density" IS '人/平方公里';

COMMENT ON COLUMN "population_grid"."data_date" IS '人口数据口径日期';

COMMENT ON COLUMN "population_grid"."source" IS '数据来源';

COMMENT ON COLUMN "population_grid"."created_at" IS '入库时间';

COMMENT ON TABLE "road_node" IS '路网节点表：步行路网拓扑节点（路口、小区出入口、过街设施），用于 15 分钟步行可达计算。';

COMMENT ON COLUMN "road_node"."id" IS '主键';

COMMENT ON COLUMN "road_node"."node_code" IS '节点编码';

COMMENT ON COLUMN "road_node"."district_id" IS '所属片区';

COMMENT ON COLUMN "road_node"."lng" IS '经度';

COMMENT ON COLUMN "road_node"."lat" IS '纬度';

COMMENT ON COLUMN "road_node"."node_type" IS '节点类型';

COMMENT ON COLUMN "road_node"."updated_at" IS '更新时间';

COMMENT ON TABLE "road_segment" IS '路网步行段表：连接两个路网节点的步行段，保存长度与步行耗时，构成 15 分钟等时圈的图结构。';

COMMENT ON COLUMN "road_segment"."id" IS '主键';

COMMENT ON COLUMN "road_segment"."segment_code" IS '路段编码';

COMMENT ON COLUMN "road_segment"."district_id" IS '所属片区';

COMMENT ON COLUMN "road_segment"."from_node_id" IS '起点节点';

COMMENT ON COLUMN "road_segment"."to_node_id" IS '终点节点';

COMMENT ON COLUMN "road_segment"."road_name" IS '道路名称';

COMMENT ON COLUMN "road_segment"."road_level" IS '道路等级';

